import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    p = data[1]

    for length in range(1, n):
        if n % length != 0:
            continue

        base = [0] * 26
        for ch in p[:length]:
            base[ord(ch) - 97] += 1

        ok = True
        for start in range(length, n, length):
            cnt = [0] * 26
            for i in range(start, start + length):
                cnt[ord(p[i]) - 97] += 1

            if cnt != base:
                ok = False
                break

        if ok:
            print(p[:length])
            return

    print("*")

if __name__ == "__main__":
    main()
